type ProfileState = "loading" | "registration" | "verification-pending" | "auth-required" | "ready" | "error";

type TrainingQuestion = {
  id: string;
  text: string;
  options: { id: string; text: string }[];
  correct: string;
  explanation: string;
};

type TrainingLesson = {
  id: string;
  title: string;
  duration: string;
  intro: string;
  callout: string;
  points: string[];
  conclusion: string;
  question: TrainingQuestion;
  theorySections?: Array<{
    title: string;
    when: string;
    examples: string[];
    note: string;
  }>;
};

type CourseProgress = {
  demos: Array<{ id: string; percent: number; completedAt: string }>;
  lessons: Array<{ id: string; percent: number; completedAt: string }>;
  blocks: Array<{ id: string; completedAt: string }>;
  videoSubmitted: boolean;
  video?: { submittedAt?: string } | null;
};

type TrainingBlock = {
  id: string;
  title: string;
  description: string;
  lessons: TrainingLesson[];
  finalQuestions: TrainingQuestion[];
};

const question = (id: string, text: string, options: [string, string][], correct: string, explanation: string): TrainingQuestion => {
  const expandedOptions: [string, string][] = options.length >= 4 ? options : [
    ...options,
    [`${id}-guess`, "Действовать наугад — порядок и контекст не имеют значения"],
    [`${id}-promise`, "Сразу дать обещание клиенту без проверки и согласования"],
  ];
  return { id, text, options: expandedOptions.map(([optionId, optionText]) => ({ id: optionId, text: optionText })), correct, explanation };
};

const lesson = (id: string, title: string, duration: string, intro: string, callout: string, points: string[], conclusion: string, check: TrainingQuestion, theorySections?: TrainingLesson["theorySections"]): TrainingLesson => ({
  id, title, duration, intro, callout, points, conclusion, question: check, theorySections,
});

