const emptyProgress: CourseProgress = { demos: [], lessons: [], blocks: [], videoSubmitted: false, video: null };

const persistLearningProgress = async (kind: "demo" | "lesson" | "block", id: string, percent = 100) => {
  const response = await fetch("/api/progress", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ kind, id, percent }) });
  const data = await response.json().catch(() => ({})) as { error?: string };
  if (!response.ok) throw new Error(data.error || "Не удалось сохранить прогресс.");
};

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) {
  return <span className={`badge badge-${tone}`}>{children}</span>;
}

function ProgressRing({ value }: { value: number }) {
  return (
    <div className="progress-ring" style={{ "--progress": `${value * 3.6}deg` } as React.CSSProperties} role="progressbar" aria-label="Прогресс курса" aria-valuemin={0} aria-valuemax={100} aria-valuenow={value}>
      <div><strong>{value}%</strong><span>курса</span></div>
    </div>
  );
}

function RegistrationGate({ state, defaultEmail, onVerificationPending }: { state: ProfileState; defaultEmail: string; onVerificationPending: (email: string) => void }) {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState(defaultEmail);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [resendStatus, setResendStatus] = useState("");

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitting(true);
    setError("");
    try {
      const response = await fetch("/api/profile", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ firstName, lastName, phone, email }),
      });
      const data = await response.json() as { verificationRequired?: boolean; email?: string; error?: string };
      if (data.verificationRequired && data.email) {
        onVerificationPending(data.email);
        return;
      }
      if (!response.ok) throw new Error(data.error || "Не удалось завершить регистрацию.");
      throw new Error("Не удалось отправить письмо для подтверждения.");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Не удалось завершить регистрацию.");
    } finally {
      setSubmitting(false);
    }
  };

  if (state === "loading") return <main className="onboarding-screen"><section className="onboarding-card onboarding-loading"><img src="/findrive-logo.jpg" alt="ФИНДРАЙВ"/><div className="onboarding-spinner"/><strong>Проверяем данные профиля…</strong></section></main>;

  if (state === "auth-required") return <main className="onboarding-screen"><section className="onboarding-card onboarding-message"><img src="/findrive-logo.jpg" alt="ФИНДРАЙВ"/><Badge tone="review">Защищённый вход</Badge><h1>Войдите в систему</h1><p>После входа откроется карточка регистрации амбассадора.</p><a className="primary-button" href="/signin-with-chatgpt?return_to=%2F">Войти и продолжить <ArrowRight size={17}/></a></section></main>;

  if (state === "verification-pending") {
    const resend = async () => {
      setSubmitting(true);
      setError("");
      setResendStatus("");
      try {
        const response = await fetch("/api/resend-verification", { method: "POST" });
        const data = await response.json() as { error?: string };
        if (!response.ok) throw new Error(data.error || "Не удалось отправить письмо повторно.");
        setResendStatus("Новое письмо отправлено. Проверьте входящие и папку «Спам». ");
      } catch (reason) {
        setError(reason instanceof Error ? reason.message : "Не удалось отправить письмо повторно.");
      } finally {
        setSubmitting(false);
      }
    };
    return <main className="onboarding-screen"><section className="onboarding-card onboarding-message verification-card"><img src="/findrive-logo.jpg" alt="ФИНДРАЙВ"/><Badge tone="review">Подтвердите почту</Badge><h1>Проверьте почту</h1><p>Ссылка подтверждения направляется на <strong>{defaultEmail}</strong>. Перейдите по кнопке «Подтвердить адрес» в письме. Если письма нет во входящих или папке «Спам», запросите повторную отправку. До подтверждения демонстрация должности и курс останутся закрыты.</p><div className="verification-actions"><button className="secondary-button" onClick={resend} disabled={submitting}>{submitting ? "Отправляем…" : "Отправить письмо повторно"}</button><button className="primary-button" onClick={() => window.location.reload()}>Я подтвердил почту <ArrowRight size={17}/></button></div>{resendStatus && <p className="verification-success"><CheckCircle2 size={16}/>{resendStatus}</p>}{error && <p className="registration-error" role="alert">{error}</p>}<small className="verification-help">Ссылка действует 24 часа и может быть использована только один раз.</small></section></main>;
  }

  if (state === "error") return <main className="onboarding-screen"><section className="onboarding-card onboarding-message"><img src="/findrive-logo.jpg" alt="ФИНДРАЙВ"/><Badge tone="danger">Ошибка соединения</Badge><h1>Профиль пока не открылся</h1><p>Обновите страницу и попробуйте ещё раз.</p><button className="primary-button" onClick={() => window.location.reload()}>Повторить</button></section></main>;

  return <main className="onboarding-screen">
    <section className="onboarding-card">
      <div className="onboarding-brand"><img src="/findrive-logo.jpg" alt="ФИНДРАЙВ — займы под залог автомобилей"/><span>АКАДЕМИЯ</span></div>
      <Badge tone="active"><CheckCircle2 size={13}/> Вход выполнен</Badge>
      <h1>Регистрация амбассадора</h1>
      <p className="onboarding-lead">Заполните карточку пользователя. После регистрации сразу откроется первый раздел демонстрации должности — «Приветствие».</p>
      <form className="registration-form" onSubmit={submit}>
        <label><span>Фамилия</span><input name="lastName" autoComplete="family-name" value={lastName} onChange={(event) => setLastName(event.target.value)} placeholder="Иванов" minLength={2} maxLength={80} required/></label>
        <label><span>Имя</span><input name="firstName" autoComplete="given-name" value={firstName} onChange={(event) => setFirstName(event.target.value)} placeholder="Иван" minLength={2} maxLength={80} required/></label>
        <label><span>Телефон</span><input name="phone" type="tel" autoComplete="tel" value={phone} onChange={(event) => setPhone(event.target.value)} placeholder="+7 999 000-00-00" minLength={10} maxLength={24} required/></label>
        <label><span>Электронная почта</span><input name="email" type="email" autoComplete="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="name@company.ru" maxLength={254} required/></label>
        {error && <p className="registration-error" role="alert">{error}</p>}
        <button className="primary-button registration-submit" disabled={submitting}>{submitting ? "Сохраняем данные…" : "Зарегистрироваться и открыть обучение"}<ArrowRight size={17}/></button>
      </form>
      <p className="registration-note"><LockKeyhole size={14}/> Данные используются для профиля и персонального прохождения обучения.</p>
    </section>
  </main>;
}

export default function Home() {
  const [view, setView] = useState<View>("position-demo");
  const [profileState, setProfileState] = useState<ProfileState>("loading");
  const [profile, setProfile] = useState<AmbassadorProfile | null>(null);
  const [registrationEmail, setRegistrationEmail] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const [copied, setCopied] = useState("");
  const [query, setQuery] = useState("");
  const [scriptIndex, setScriptIndex] = useState(0);
  const [quizAnswer, setQuizAnswer] = useState<string | null>(null);
  const [courseProgress, setCourseProgress] = useState<CourseProgress>(emptyProgress);
  const [dashboardTarget, setDashboardTarget] = useState("");

  const filteredScripts = useMemo(() => scripts.filter((item) => `${item.title} ${item.tag} ${item.safe}`.toLowerCase().includes(query.toLowerCase())), [query]);

  useEffect(() => {
    let active = true;
    fetch("/api/profile", { cache: "no-store" }).then(async (response) => {
      const data = await response.json().catch(() => ({})) as { profile?: AmbassadorProfile; email?: string };
      if (!active) return;
      if (response.ok && data.profile) {
        setProfile(data.profile);
        setProfileState("ready");
        const linkedUser = data.profile.role === "admin" ? new URLSearchParams(window.location.search).get("dashboard_user") || "" : "";
        setDashboardTarget(linkedUser);
        fetch("/api/progress", { cache: "no-store" }).then(async (progressResponse) => {
          if (progressResponse.ok) {
            const loadedProgress = await progressResponse.json() as CourseProgress;
            setCourseProgress(loadedProgress);
            const completedDemo = (loadedProgress.demos || []).filter((item) => item.percent >= 100).length === jobDemoLessons.length;
            setView(linkedUser ? "analytics" : completedDemo ? "course" : "position-demo");
          } else {
            setView(linkedUser ? "analytics" : "position-demo");
          }
        }).catch(() => undefined);
      } else if (response.status === 409) {
        setRegistrationEmail(data.email || "");
        setProfileState("verification-pending");
      } else if (response.status === 404) {
        setRegistrationEmail(data.email || "");
        setProfileState("registration");
      } else if (response.status === 401) {
        setProfileState("auth-required");
      } else {
        setProfileState("error");
      }
    }).catch(() => active && setProfileState("error"));
    return () => { active = false; };
  }, []);

  useEffect(() => {
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const coarsePointer = window.matchMedia("(pointer: coarse)");
    if (reducedMotion.matches || coarsePointer.matches) return;
    let animationFrame = 0;
    const setParallax = (event: PointerEvent) => {
      window.cancelAnimationFrame(animationFrame);
      animationFrame = window.requestAnimationFrame(() => {
        const x = (event.clientX / window.innerWidth - 0.5) * 2;
        const y = (event.clientY / window.innerHeight - 0.5) * 2;
        document.documentElement.style.setProperty("--parallax-x", `${x * 22}px`);
        document.documentElement.style.setProperty("--parallax-y", `${y * 18}px`);
        document.documentElement.style.setProperty("--parallax-x-reverse", `${x * -14}px`);
        document.documentElement.style.setProperty("--parallax-y-reverse", `${y * -11}px`);
      });
    };
    const resetParallax = () => {
      document.documentElement.style.setProperty("--parallax-x", "0px");
      document.documentElement.style.setProperty("--parallax-y", "0px");
      document.documentElement.style.setProperty("--parallax-x-reverse", "0px");
      document.documentElement.style.setProperty("--parallax-y-reverse", "0px");
    };
    window.addEventListener("pointermove", setParallax, { passive: true });
    window.addEventListener("pointerleave", resetParallax);
    return () => {
      window.cancelAnimationFrame(animationFrame);
      window.removeEventListener("pointermove", setParallax);
      window.removeEventListener("pointerleave", resetParallax);
      resetParallax();
    };
  }, []);

  const copyText = async (text: string, key: string) => {
    await navigator.clipboard?.writeText(text);
    setCopied(key);
    window.setTimeout(() => setCopied(""), 1800);
  };

  const demoComplete = (courseProgress.demos || []).filter((item) => item.percent >= 100).length === jobDemoLessons.length;

  const navigate = (next: View) => {
    const canOpenAdminDashboard = next === "analytics" && profile?.role === "admin";
    setView(!demoComplete && next !== "position-demo" && !canOpenAdminDashboard ? "position-demo" : next);
    setMenuOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  if (profileState !== "ready" || !profile) {
    return <RegistrationGate state={profileState} defaultEmail={registrationEmail} onVerificationPending={(email) => {
      setRegistrationEmail(email);
      setProfileState("verification-pending");
      window.scrollTo({ top: 0 });
    }}/>;
  }

  const fullName = `${profile.lastName} ${profile.firstName}`;
  const initials = `${profile.firstName[0] || ""}${profile.lastName[0] || ""}`.toUpperCase();
  const personalProgress = Math.round(((courseProgress.lessons.filter((item) => item.percent >= 100).length + courseProgress.blocks.length + (courseProgress.videoSubmitted ? 1 : 0)) / (lessonCatalog.length + learningBlocks.length + 1)) * 100);

  return (
    <div className="app-shell">
      <div className="parallax-backdrop" aria-hidden="true"><span/><span/><span/></div>
      <aside className={`sidebar ${menuOpen ? "sidebar-open" : ""}`} aria-label="Основная навигация">
        <div className="brand">
          <img className="brand-logo" src="/findrive-logo.jpg" alt="ФИНДРАЙВ — займы под залог автомобилей" />
          <span className="brand-academy">АКАДЕМИЯ</span>
          <button className="icon-button mobile-close" onClick={() => setMenuOpen(false)} aria-label="Закрыть меню"><X size={20} /></button>
        </div>
        <nav>
          {nav.filter((item) => item.id !== "analytics" || profile.role === "admin").filter((item) => demoComplete || item.id === "position-demo" || (item.id === "analytics" && profile.role === "admin")).filter((item) => item.id !== "video-card" || courseProgress.blocks.length === learningBlocks.length).map((item) => {
            const Icon = item.icon;
            return <button key={item.id} className={view === item.id ? "nav-item active" : "nav-item"} onClick={() => navigate(item.id)}><Icon size={19} /><span>{item.label}</span>{item.id === "documents" && <i>2</i>}</button>;
          })}
        </nav>
        <div className="sidebar-bottom">
          <div className="access-card">
            <div className="access-icon"><LockKeyhole size={18} /></div>
            <div><span>Допуск к работе</span><strong>Юридические лица</strong></div>
          </div>
          <button className="user-card" aria-label="Открыть профиль">
            <span className="avatar">{initials}</span>
            <span><strong>{fullName}</strong><small>{profile.role === "admin" ? "Администратор" : "Амбассадор"}</small></span>
            <Settings2 size={17} />
          </button>
        </div>
      </aside>

      <main>
        <header className="topbar">
          <button className="icon-button menu-button" onClick={() => setMenuOpen(true)} aria-label="Открыть меню"><Menu size={22} /></button>
          <div className="global-search"><Search size={18} /><input aria-label="Поиск по базе знаний" placeholder="Найти в базе знаний" onFocus={() => navigate("scripts")} /></div>
          <div className="top-actions"><Badge tone="demo">Демо-версия</Badge><button className="icon-button notification" aria-label="Уведомления"><Bell size={20} /><i /></button></div>
        </header>

        <div className="content">
          {view === "position-demo" && <PositionDemo firstName={profile.firstName} progress={courseProgress} onProgress={setCourseProgress} onComplete={() => navigate("course")} />}
          {view === "dashboard" && <Dashboard firstName={profile.firstName} progressPercent={personalProgress} onNavigate={navigate} onLesson={() => navigate("course")} copied={copied} onCopy={copyText} />}
          {view === "course" && <Course progress={courseProgress} onProgress={setCourseProgress} onVideoCard={() => navigate(courseProgress.videoSubmitted ? "thanks" : "video-card")} />}
          {view === "scripts" && <Scripts query={query} setQuery={setQuery} filtered={filteredScripts} active={scriptIndex} setActive={setScriptIndex} copied={copied} onCopy={copyText} />}
          {view === "leads" && <Leads />}
          {view === "payouts" && <Payouts />}
          {view === "documents" && <Documents />}
          {view === "control" && <Control quizAnswer={quizAnswer} setQuizAnswer={setQuizAnswer} />}
          {view === "analytics" && profile.role === "admin" && <TeamDashboard highlightUserId={dashboardTarget} />}
          {view === "video-card" && <VideoCard onSubmitted={(submittedAt) => { setCourseProgress((current) => ({ ...current, videoSubmitted: true, video: { submittedAt } })); navigate("thanks"); }} />}
          {view === "thanks" && <ThankYou firstName={profile.firstName} />}
        </div>
      </main>

    </div>
  );
}

