function PositionDemo({ firstName, progress, onProgress, onComplete }: { firstName: string; progress: CourseProgress; onProgress: React.Dispatch<React.SetStateAction<CourseProgress>>; onComplete: () => void }) {
  const initialCompleted = (progress.demos || []).filter((item) => item.percent >= 100).map((item) => item.id);
  const [completed, setCompleted] = useState<string[]>(initialCompleted);
  const [lessonIndex, setLessonIndex] = useState(() => {
    const firstIncomplete = jobDemoLessons.findIndex((item) => !initialCompleted.includes(item.id));
    return firstIncomplete === -1 ? jobDemoLessons.length - 1 : firstIncomplete;
  });
  const [answer, setAnswer] = useState("");
  const [videoUrls, setVideoUrls] = useState<Record<string, string>>({});
  const [videoNames, setVideoNames] = useState<Record<string, string>>({});
  const [videoError, setVideoError] = useState("");
  const [progressError, setProgressError] = useState("");
  const currentLesson = jobDemoLessons[lessonIndex];
  const isCompleted = completed.includes(currentLesson.id);
  const answerCorrect = answer === currentLesson.question.correct;
  const canContinue = isCompleted || answerCorrect;
  const percent = Math.round((completed.length / jobDemoLessons.length) * 100);

  useEffect(() => {
    if (isCompleted) return;
    void persistLearningProgress("demo", currentLesson.id, 25).catch(() => undefined);
  }, [currentLesson.id, isCompleted]);

  const lessonUnlocked = (index: number) => index === 0 || jobDemoLessons.slice(0, index).every((item) => completed.includes(item.id));

  const openDemoLesson = (index: number) => {
    if (!lessonUnlocked(index)) return;
    setLessonIndex(index);
    setAnswer("");
    setVideoError("");
    setProgressError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const uploadVideo = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.currentTarget.files?.[0];
    if (!file) return;
    if (file.type !== "video/mp4" && !file.name.toLowerCase().endsWith(".mp4")) {
      setVideoError("Поддерживается только видео в формате MP4.");
      event.currentTarget.value = "";
      return;
    }
    const previousUrl = videoUrls[currentLesson.id];
    if (previousUrl) URL.revokeObjectURL(previousUrl);
    setVideoUrls((current) => ({ ...current, [currentLesson.id]: URL.createObjectURL(file) }));
    setVideoNames((current) => ({ ...current, [currentLesson.id]: file.name }));
    setVideoError("");
  };

  const chooseAnswer = (optionId: string) => {
    setAnswer(optionId);
    if (isCompleted) return;
    const answerProgress = optionId === currentLesson.question.correct ? 90 : 70;
    void persistLearningProgress("demo", currentLesson.id, answerProgress).catch(() => undefined);
  };

  const finishLesson = async () => {
    if (!canContinue) return;
    if (!isCompleted) {
      setProgressError("");
      try {
        await persistLearningProgress("demo", currentLesson.id, 100);
      } catch (reason) {
        setProgressError(reason instanceof Error ? reason.message : "Не удалось сохранить прогресс.");
        return;
      }
      const completedAt = new Date().toISOString();
      setCompleted((current) => current.includes(currentLesson.id) ? current : [...current, currentLesson.id]);
      onProgress((current) => ({ ...current, demos: (current.demos || []).some((item) => item.id === currentLesson.id) ? current.demos.map((item) => item.id === currentLesson.id ? { ...item, percent: 100, completedAt } : item) : [...(current.demos || []), { id: currentLesson.id, percent: 100, completedAt }] }));
    }
    if (lessonIndex === jobDemoLessons.length - 1) {
      onComplete();
    } else {
      setLessonIndex(lessonIndex + 1);
      setAnswer("");
      setVideoError("");
      setProgressError("");
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  return <>
    <section className="page-heading learning-heading demo-heading">
      <div><Badge tone="active">Обязательный вводный этап</Badge><h1>Демонстрация должности &quot;Амбассадор&quot; / Партнер по привлечению инвестиций</h1><p>Познакомьтесь с компанией, функционалом позиции амбассадор и его ролью. После этого Вам откроется основной курс обучения по привлечению инвестиций.</p></div>
      <div className="heading-stat"><strong>{percent}%</strong><span>{completed.length} из {jobDemoLessons.length} тем</span></div>
    </section>
    <section className="demo-route card"><div><Sparkles size={22}/><span><small>Ваш маршрут</small><strong>Регистрация → демонстрация должности → курс амбассадора</strong></span></div><i><b style={{ width: `${percent}%` }}/></i></section>
    <section className="learning-workspace card position-workspace">
      <aside className="lesson-sidebar">
        <div className="lesson-sidebar-head"><small>Вводный модуль</small><h2>Демонстрация должности &quot;Амбассадор&quot;</h2><p>Темы открываются последовательно после короткой проверки знаний.</p></div>
        <div className="lesson-nav">
          {jobDemoLessons.map((item, index) => {
            const unlocked = lessonUnlocked(index);
            const done = completed.includes(item.id);
            return <button key={item.id} className={`${lessonIndex === index ? "active" : ""} ${done ? "done" : ""}`} disabled={!unlocked} onClick={() => openDemoLesson(index)}><span>{done ? <Check size={13}/> : unlocked ? index + 1 : <LockKeyhole size={12}/>}</span><strong>{item.title}</strong></button>;
          })}
        </div>
        <div className="lesson-sidebar-progress"><div><span style={{ width: `${percent}%` }}/></div><small>Прогресс</small><strong>{completed.length}/{jobDemoLessons.length}</strong></div>
      </aside>
      <div className="lesson-stage">
        <header className="lesson-stage-head"><small>Тема {lessonIndex + 1} из {jobDemoLessons.length}</small><h2>{currentLesson.title}</h2><span><Clock3 size={14}/>{currentLesson.duration}</span></header>
        <section className="video-learning-card" aria-label={`Видео к теме ${currentLesson.title}`}>
          {videoUrls[currentLesson.id] ? <><video key={videoUrls[currentLesson.id]} controls preload="metadata"><source src={videoUrls[currentLesson.id]} type="video/mp4"/>Ваш браузер не поддерживает видео MP4.</video><div className="video-meta"><div><strong>{videoNames[currentLesson.id]}</strong><small>Текст темы полностью открыт ниже — просмотр видео не блокирует чтение.</small></div><label className="video-replace">Заменить MP4<input type="file" accept="video/mp4,.mp4" onChange={uploadVideo}/></label></div></> : <label className="video-upload-zone"><span><Sparkles size={28}/></span><strong>Загрузите видео к теме</strong><small>Одно видео в формате MP4. Текстовая часть уже доступна ниже и не зависит от просмотра.</small><em>Выбрать MP4</em><input type="file" accept="video/mp4,.mp4" onChange={uploadVideo}/></label>}
          {videoError && <p className="video-error" role="alert">{videoError}</p>}
        </section>
        <div className="lesson-reading">
          {currentLesson.id === "demo-welcome" ? <>
            <p className="lesson-intro welcome-line">{firstName}, добро пожаловать в Академию ФИНДРАЙВ!</p>
            <p className="lesson-intro welcome-description">Пройди небольшую демонстрацию должности, которая поможет тебе увидеть работу амбассадора от первого знакомства с компанией до выплаты вознаграждения.</p>
          </> : <p className="lesson-intro">{currentLesson.intro}</p>}
          <aside className="green-callout"><CheckCircle2 size={20}/><p>{currentLesson.callout}</p></aside>
          <div className="lesson-points"><h3>Что важно запомнить:</h3><ul>{currentLesson.points.map((point) => <li key={point}><Check size={15}/><span>{point}</span></li>)}</ul></div>
          <aside className="green-callout strong"><CheckCircle2 size={20}/><p>{currentLesson.conclusion}</p></aside>
          <section className="lesson-question-card"><small>Экспресс-тест</small><h3>{currentLesson.question.text}</h3><div>{currentLesson.question.options.map((option) => <button key={option.id} className={answer === option.id ? "selected" : ""} onClick={() => chooseAnswer(option.id)}><span>{answer === option.id ? <Check size={13}/> : null}</span>{option.text}</button>)}</div>{answer && <p className={answerCorrect ? "answer-good" : "answer-bad"}>{answerCorrect ? currentLesson.question.explanation : "Пока неверно. Вернитесь к ключевым пунктам и попробуйте ещё раз."}</p>}</section>
          {progressError && <p className="video-error" role="alert">{progressError}</p>}
          <footer className="lesson-next"><button className="primary-button" disabled={!canContinue} onClick={finishLesson}>{lessonIndex === jobDemoLessons.length - 1 ? "Завершить и перейти к курсу" : "Следующая тема"}<ChevronRight size={17}/></button><small>{lessonIndex < jobDemoLessons.length - 1 ? `Далее: ${jobDemoLessons[lessonIndex + 1].title}` : "После ответа автоматически откроется курс амбассадора"}</small></footer>
        </div>
      </div>
    </section>
  </>;
}

function Course({ progress, onProgress, onVideoCard }: { progress: CourseProgress; onProgress: React.Dispatch<React.SetStateAction<CourseProgress>>; onVideoCard: () => void }) {
  const [blockIndex, setBlockIndex] = useState(0);
  const [lessonIndex, setLessonIndex] = useState(0);
  const [completedLessons, setCompletedLessons] = useState<string[]>(progress.lessons.filter((item) => item.percent >= 100).map((item) => item.id));
  const [completedBlocks, setCompletedBlocks] = useState<string[]>(progress.blocks.map((item) => item.id));
  const [lessonAnswer, setLessonAnswer] = useState("");
  const [finalAnswers, setFinalAnswers] = useState<Record<string, string>>({});
  const [videoUrls, setVideoUrls] = useState<Record<string, string>>({});
  const [videoNames, setVideoNames] = useState<Record<string, string>>({});
  const [videoError, setVideoError] = useState("");
  const [progressError, setProgressError] = useState("");

  const block = learningBlocks[blockIndex];
  const isFinalTest = lessonIndex === block.lessons.length;
  const currentLesson = isFinalTest ? null : block.lessons[lessonIndex];
  const finishedInBlock = block.lessons.filter((item) => completedLessons.includes(item.id)).length;
  const allLessonsFinished = finishedInBlock === block.lessons.length;
  const currentBlockCompleted = completedBlocks.includes(block.id);
  const totalSteps = learningBlocks.reduce((sum, item) => sum + item.lessons.length + 1, 0);
  const completedSteps = completedLessons.length + completedBlocks.length;
  const overallProgress = Math.round((completedSteps / totalSteps) * 100);

  const blockUnlocked = (index: number) => index === 0 || learningBlocks.slice(0, index).every((item) => completedBlocks.includes(item.id));
  const lessonUnlocked = (index: number) => index === 0 || block.lessons.slice(0, index).every((item) => completedLessons.includes(item.id));
  const finalPassed = block.finalQuestions.every((item) => finalAnswers[item.id] === item.correct);
  const lessonCompleted = currentLesson ? completedLessons.includes(currentLesson.id) : false;
  const lessonAnswerCorrect = currentLesson ? lessonAnswer === currentLesson.question.correct : false;
  const canContinueLesson = lessonCompleted || lessonAnswerCorrect;

  useEffect(() => {
    if (!currentLesson || lessonCompleted) return;
    void persistLearningProgress("lesson", currentLesson.id, 25).catch(() => undefined);
  }, [currentLesson?.id, lessonCompleted]);

  const openBlock = (index: number) => {
    if (!blockUnlocked(index)) return;
    const selected = learningBlocks[index];
    const nextLesson = selected.lessons.findIndex((item) => !completedLessons.includes(item.id));
    setBlockIndex(index);
    setLessonIndex(nextLesson === -1 ? selected.lessons.length : nextLesson);
    setFinalAnswers({});
    setLessonAnswer("");
    setVideoError("");
    setProgressError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const openLesson = (index: number) => {
    const available = index < block.lessons.length ? lessonUnlocked(index) : allLessonsFinished;
    if (!available) return;
    setLessonIndex(index);
    setLessonAnswer("");
    setVideoError("");
    setProgressError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const uploadVideo = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (!currentLesson) return;
    const file = event.currentTarget.files?.[0];
    if (!file) return;
    const isMp4 = file.type === "video/mp4" || file.name.toLowerCase().endsWith(".mp4");
    if (!isMp4) {
      setVideoError("Поддерживается только видео в формате MP4.");
      event.currentTarget.value = "";
      return;
    }
    const previousUrl = videoUrls[currentLesson.id];
    if (previousUrl) URL.revokeObjectURL(previousUrl);
    const nextUrl = URL.createObjectURL(file);
    setVideoUrls((current) => ({ ...current, [currentLesson.id]: nextUrl }));
    setVideoNames((current) => ({ ...current, [currentLesson.id]: file.name }));
    setVideoError("");
  };

  const saveProgress = (kind: "lesson" | "block", id: string) => persistLearningProgress(kind, id, 100);

  const chooseLessonAnswer = (optionId: string) => {
    setLessonAnswer(optionId);
    if (!currentLesson || lessonCompleted) return;
    const answerProgress = optionId === currentLesson.question.correct ? 90 : 70;
    void persistLearningProgress("lesson", currentLesson.id, answerProgress).catch(() => undefined);
  };

  const completeLesson = async () => {
    if (!currentLesson || !canContinueLesson) return;
    setProgressError("");
    try {
      await saveProgress("lesson", currentLesson.id);
    } catch (reason) {
      setProgressError(reason instanceof Error ? reason.message : "Не удалось сохранить прогресс.");
      return;
    }
    const completedAt = new Date().toISOString();
    setCompletedLessons((current) => current.includes(currentLesson.id) ? current : [...current, currentLesson.id]);
    onProgress((current) => ({ ...current, lessons: current.lessons.some((item) => item.id === currentLesson.id) ? current.lessons.map((item) => item.id === currentLesson.id ? { ...item, percent: 100, completedAt } : item) : [...current.lessons, { id: currentLesson.id, percent: 100, completedAt }] }));
    setLessonAnswer("");
    setVideoError("");
    setLessonIndex(Math.min(lessonIndex + 1, block.lessons.length));
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const completeBlock = async () => {
    if (!finalPassed && !currentBlockCompleted) return;
    if (!currentBlockCompleted) {
      setProgressError("");
      try {
        await saveProgress("block", block.id);
      } catch (reason) {
        setProgressError(reason instanceof Error ? reason.message : "Не удалось сохранить прогресс.");
        return;
      }
    }
    const completedAt = new Date().toISOString();
    setCompletedBlocks((current) => current.includes(block.id) ? current : [...current, block.id]);
    onProgress((current) => ({ ...current, blocks: current.blocks.some((item) => item.id === block.id) ? current.blocks : [...current.blocks, { id: block.id, completedAt }] }));
    if (blockIndex < learningBlocks.length - 1) {
      setBlockIndex(blockIndex + 1);
      setLessonIndex(0);
      setFinalAnswers({});
      setLessonAnswer("");
      setVideoError("");
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  return <>
    <section className="page-heading learning-heading">
      <div><Badge tone="date">Программа амбассадора</Badge><h1>Последовательное обучение</h1><p>Видео и текст урока доступны сразу. Следующий блок откроется только после итогового теста.</p></div>
      <div className="heading-stat"><strong>{overallProgress}%</strong><span>{completedSteps} из {totalSteps} шагов</span></div>
    </section>

    <nav className="learning-blocks" aria-label="Блоки обучения">
      {learningBlocks.map((item, index) => {
        const unlocked = blockUnlocked(index);
        const done = completedBlocks.includes(item.id);
        return <button key={item.id} className={`${index === blockIndex ? "active" : ""} ${done ? "done" : ""}`} disabled={!unlocked} onClick={() => openBlock(index)}>
          <span>{done ? <Check size={16}/> : unlocked ? index + 1 : <LockKeyhole size={14}/>}</span>
          <div><strong>{item.title}</strong><small>{done ? "Блок завершён" : unlocked ? "Доступен" : "Откроется позже"}</small></div>
        </button>;
      })}
    </nav>

    <section className="learning-workspace card">
      <aside className="lesson-sidebar">
        <div className="lesson-sidebar-head"><small>Блок {blockIndex + 1}</small><h2>{block.title}</h2><p>{block.description}</p></div>
        <div className="lesson-nav">
          {block.lessons.map((item, index) => {
            const unlocked = lessonUnlocked(index);
            const done = completedLessons.includes(item.id);
            return <button key={item.id} className={`${lessonIndex === index ? "active" : ""} ${done ? "done" : ""}`} disabled={!unlocked} onClick={() => openLesson(index)}>
              <span>{done ? <Check size={13}/> : unlocked ? index + 1 : <LockKeyhole size={12}/>}</span><strong>{item.title}</strong>
            </button>;
          })}
          <button className={`${isFinalTest ? "active" : ""} ${currentBlockCompleted ? "done" : ""}`} disabled={!allLessonsFinished} onClick={() => openLesson(block.lessons.length)}>
            <span>{currentBlockCompleted ? <Check size={13}/> : allLessonsFinished ? <ClipboardCheck size={13}/> : <LockKeyhole size={12}/>}</span><strong>Итоговый тест блока</strong>
          </button>
        </div>
        <div className="lesson-sidebar-progress"><div><span style={{width:`${Math.round((finishedInBlock / block.lessons.length) * 100)}%`}}/></div><small>Прогресс</small><strong>{finishedInBlock}/{block.lessons.length}</strong></div>
      </aside>

      <div className="lesson-stage">
        {currentLesson ? <>
          <header className="lesson-stage-head"><small>Урок {lessonIndex + 1} из {block.lessons.length}</small><h2>{currentLesson.title}</h2><span><Clock3 size={14}/>{currentLesson.duration}</span></header>

          <section className="video-learning-card" aria-label={`Видео к уроку ${currentLesson.title}`}>
            {videoUrls[currentLesson.id] ? <>
              <video key={videoUrls[currentLesson.id]} controls preload="metadata">
                <source src={videoUrls[currentLesson.id]} type="video/mp4" />
                Ваш браузер не поддерживает видео MP4.
              </video>
              <div className="video-meta"><div><strong>{videoNames[currentLesson.id]}</strong><small>Текст урока уже доступен ниже — видео можно смотреть в удобном темпе</small></div><label className="video-replace">Заменить MP4<input type="file" accept="video/mp4,.mp4" onChange={uploadVideo}/></label></div>
            </> : <label className="video-upload-zone">
              <span><BookOpen size={28}/></span><strong>Загрузите видео к уроку</strong><small>Одно видео в формате MP4. Текстовая часть урока доступна независимо от загрузки и просмотра видео.</small><em>Выбрать MP4</em><input type="file" accept="video/mp4,.mp4" onChange={uploadVideo}/>
            </label>}
            {videoError && <p className="video-error" role="alert">{videoError}</p>}
          </section>

          <div className="lesson-reading">
            <p className="lesson-intro">{currentLesson.intro}</p>
            <aside className="green-callout"><CheckCircle2 size={20}/><p>{currentLesson.callout}</p></aside>
            <div className="lesson-points"><h3>Ключевые пункты:</h3><ul>{currentLesson.points.map((point) => <li key={point}><Check size={15}/><span>{point}</span></li>)}</ul></div>
            {currentLesson.theorySections?.length ? <section className="spin-theory"><h3>Когда применять каждый тип вопроса</h3><div className="spin-theory-grid">{currentLesson.theorySections.map((section, index) => <article key={section.title}><span>{index + 1}</span><h4>{section.title}</h4><p>{section.when}</p><strong>Примеры:</strong><ul>{section.examples.map((example) => <li key={example}>«{example}»</li>)}</ul><aside><CheckCircle2 size={15}/>{section.note}</aside></article>)}</div></section> : null}
            <aside className="green-callout strong"><CheckCircle2 size={20}/><p>{currentLesson.conclusion}</p></aside>

            <section className="lesson-question-card">
              <h3>{currentLesson.question.text}</h3>
              <div>{currentLesson.question.options.map((option) => <button key={option.id} className={lessonAnswer === option.id ? "selected" : ""} onClick={() => chooseLessonAnswer(option.id)}><span>{lessonAnswer === option.id ? <Check size={13}/> : null}</span>{option.text}</button>)}</div>
              {lessonAnswer && <p className={lessonAnswerCorrect ? "answer-good" : "answer-bad"}>{lessonAnswerCorrect ? currentLesson.question.explanation : "Пока неверно. Вернитесь к ключевым пунктам и попробуйте ещё раз."}</p>}
            </section>

            <footer className="lesson-next"><button className="primary-button" disabled={!canContinueLesson} onClick={completeLesson}>{lessonIndex === block.lessons.length - 1 ? "Перейти к тесту блока" : "Следующий урок"}<ChevronRight size={17}/></button><small>{lessonIndex < block.lessons.length - 1 ? `Следующий урок: ${block.lessons[lessonIndex + 1].title}` : "После урока откроется итоговый тест блока"}</small></footer>
          </div>
        </> : <section className="block-final-test">
          <Badge tone={currentBlockCompleted ? "active" : "review"}>{currentBlockCompleted ? "Блок завершён" : "Итоговый тест"}</Badge>
          <h2>{block.title}</h2><p>Ответьте правильно на все вопросы. Только после этого откроется следующий блок.</p>
          <div className="final-question-list">{block.finalQuestions.map((item, index) => {
            const selected = finalAnswers[item.id];
            const correct = selected === item.correct;
            return <article key={item.id}><small>Вопрос {index + 1} из {block.finalQuestions.length}</small><h3>{item.text}</h3><div>{item.options.map((option) => <button key={option.id} className={selected === option.id ? "selected" : ""} onClick={() => setFinalAnswers((current) => ({...current,[item.id]:option.id}))}><span>{selected === option.id ? <Check size={13}/> : null}</span>{option.text}</button>)}</div>{selected && <p className={correct ? "answer-good" : "answer-bad"}>{correct ? item.explanation : "Неверный ответ. Повторите уроки блока и попробуйте ещё раз."}</p>}</article>;
          })}</div>
          {progressError && <p className="video-error" role="alert">{progressError}</p>}
          {currentBlockCompleted && blockIndex === learningBlocks.length - 1 ? <div className="course-complete"><Award size={28}/><div><strong>Учебные блоки завершены</strong><p>{progress.videoSubmitted ? "Видеовизитка загружена — полезные материалы доступны." : "Остался финальный шаг — двухминутная видеовизитка."}</p><button className="primary-button" onClick={onVideoCard}>{progress.videoSubmitted ? "Открыть полезные материалы" : "Записать видеовизитку"}<ChevronRight size={17}/></button></div></div> : <footer className="lesson-next"><button className="primary-button" disabled={!finalPassed && !currentBlockCompleted} onClick={completeBlock}>{blockIndex === learningBlocks.length - 1 ? "Завершить программу" : "Завершить блок и открыть следующий"}<ChevronRight size={17}/></button><small>Проходной результат: 100%</small></footer>}
        </section>}
      </div>
    </section>
  </>;
}

const lessonCatalog = learningBlocks.flatMap((block, blockIndex) => block.lessons.map((item, lessonIndex) => ({ ...item, blockTitle: block.title, order: learningBlocks.slice(0, blockIndex).reduce((sum, entry) => sum + entry.lessons.length, 0) + lessonIndex + 1 })));

type DashboardUser = {
  id: string;
  firstName: string;
  lastName: string;
  registeredAt?: string;
  createdAt: string;
  phone?: string;
  email?: string;
  demoProgressPercent: number;
  progressPercent: number;
  demos: Array<{ id: string; percent: number; completedAt: string }>;
  lessons: Array<{ id: string; percent: number; completedAt: string }>;
  blocks: Array<{ id: string; completedAt: string }>;
  video?: { submittedAt?: string } | null;
};

const formatMoment = (value?: string) => value ? new Intl.DateTimeFormat("ru-RU", { dateStyle: "short", timeStyle: "short" }).format(new Date(value)) : "—";
const formatElapsed = (start?: string, end?: string, now = Date.now()) => {
  if (!start) return "—";
  const milliseconds = Math.max(0, (end ? new Date(end).getTime() : now) - new Date(start).getTime());
  const days = Math.floor(milliseconds / 86_400_000);
  const hours = Math.floor((milliseconds % 86_400_000) / 3_600_000);
  return `${days} дн. ${hours} ч.`;
};

function TeamDashboard({ highlightUserId = "" }: { highlightUserId?: string }) {
  const [users, setUsers] = useState<DashboardUser[]>([]);
  const [refreshedAt, setRefreshedAt] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [now, setNow] = useState(() => Date.now());
  const [emailConfigured, setEmailConfigured] = useState(true);

  const load = async () => {
    try {
      const response = await fetch("/api/dashboard", { cache: "no-store" });
      const data = await response.json() as { users?: DashboardUser[]; refreshedAt?: string; emailConfigured?: boolean; error?: string };
      if (!response.ok) throw new Error(data.error || "Не удалось загрузить дашборд.");
      setUsers(data.users || []);
      setRefreshedAt(data.refreshedAt || new Date().toISOString());
      setEmailConfigured(data.emailConfigured !== false);
      setError("");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Не удалось загрузить дашборд.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const initialTimer = window.setTimeout(load, 0);
    const refreshTimer = window.setInterval(load, 15_000);
    const clockTimer = window.setInterval(() => setNow(Date.now()), 60_000);
    return () => { window.clearTimeout(initialTimer); window.clearInterval(refreshTimer); window.clearInterval(clockTimer); };
  }, []);

  const completed = users.filter((user) => user.progressPercent === 100).length;
  const active = users.filter((user) => user.progressPercent > 0 && user.progressPercent < 100).length;
  const average = users.length ? Math.round(users.reduce((sum, user) => sum + user.progressPercent, 0) / users.length) : 0;

  return <>
    <section className="page-heading dashboard-heading"><div><Badge tone="active">Онлайн · обновление каждые 15 секунд</Badge><h1>Дашборд обучения</h1><p>Прогресс зарегистрированных пользователей по данным платформы.</p></div><button className="secondary-button" onClick={load}>Обновить сейчас</button></section>
    <section className="dashboard-kpis"><article className="card"><span>Зарегистрировано</span><strong>{users.length}</strong></article><article className="card"><span>Проходят курс</span><strong>{active}</strong></article><article className="card"><span>Завершили</span><strong>{completed}</strong></article><article className="card"><span>Средний прогресс</span><strong>{average}%</strong></article></section>
    {!emailConfigured && <section className="email-setup-alert"><AlertTriangle size={20}/><div><strong>Почтовые уведомления ожидают подключения отправителя</strong><p>События уже фиксируются и будут повторно отправлены после настройки почтового ключа.</p></div></section>}
    {error && <p className="video-error" role="alert">{error}</p>}
    <section className="card learners-dashboard">
      <div className="dashboard-list-head">
        <div><strong>Детализация прохождения по каждому пользователю</strong><small>Все уроки, тесты и время прохождения показаны без скрытых разделов</small></div>
        <small>{loading ? "Загрузка…" : `Обновлено ${formatMoment(refreshedAt)}`}</small>
      </div>
      <div className="learner-rows">{users.map((user) => {
        const start = user.registeredAt || user.createdAt;
        const demoProgressById = new Map((user.demos || []).map((item) => [item.id, item]));
        const lessonProgressById = new Map((user.lessons || []).map((item) => [item.id, item]));
        const blockCompletionById = new Map((user.blocks || []).map((item) => [item.id, item]));
        return <article className={`learner-card ${user.id === highlightUserId ? "highlighted" : ""}`} key={user.id}>
          <header className="learner-overview">
            <div className="learner-person"><span>{`${user.firstName?.[0] || ""}${user.lastName?.[0] || ""}`.toUpperCase()}</span><strong>{user.lastName} {user.firstName}</strong></div>
            <div><small>Регистрация</small><strong>{formatMoment(start)}</strong></div>
            <div><small>Время в программе</small><strong>{formatElapsed(start, user.video?.submittedAt, now)}</strong></div>
            <div className="learner-progress"><small>Весь курс</small><strong>{user.progressPercent}%</strong><i><b style={{ width: `${user.progressPercent}%` }}/></i></div>
          </header>
          <div className="lesson-progress-detail">
            <div className="learner-questionnaire">
              <div><small>Телефон</small><strong>{user.phone || "—"}</strong></div>
              <div><small>Электронная почта</small><strong>{user.email || "—"}</strong></div>
              <div><small>Дата регистрации</small><strong>{formatMoment(start)}</strong></div>
              <div><small>Демонстрация должности</small><strong>{user.demoProgressPercent}%</strong></div>
            </div>
            <section className="progress-section" aria-label={`Демонстрация должности: ${user.lastName} ${user.firstName}`}>
              <div className="lesson-progress-head"><strong>Демонстрация должности — каждый урок</strong><span>{user.demoProgressPercent === 100 ? "Завершена" : `${user.demoProgressPercent}% пройдено`}</span></div>
              <div className="lesson-table-head" aria-hidden="true"><span>№</span><span>Урок</span><span>Пройдено</span><span>Статус</span><span>Прогресс</span><span>Дата и время</span></div>
              {jobDemoLessons.map((demo, index) => {
                const saved = demoProgressById.get(demo.id);
                const percent = saved?.percent || 0;
                return <div className="lesson-progress-line demo-progress-line" key={demo.id}><span>{index + 1}</span><div><strong>{demo.title}</strong><small>Демонстрация должности</small></div><i className="lesson-progress-track" role="progressbar" aria-label={`Пройдено ${percent}% урока ${demo.title}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent}><span style={{ width: `${percent}%` }}/></i><em className={`progress-status ${percent === 100 ? "done" : percent > 0 ? "started" : "idle"}`}>{percent === 100 ? "Пройден" : percent > 0 ? "В процессе" : "Не начат"}</em><b>{percent}%</b><time>{saved ? formatMoment(saved.completedAt) : "—"}</time></div>;
              })}
            </section>
            <section className="progress-section course-progress-section" aria-label={`Учебный курс: ${user.lastName} ${user.firstName}`}>
              <div className="lesson-progress-head course-progress-head"><strong>Прохождение каждого урока курса</strong><span>{user.video ? `Видеовизитка: ${formatMoment(user.video.submittedAt)}` : "Видеовизитка не загружена"}</span></div>
              {learningBlocks.map((block, blockIndex) => {
                const blockResult = blockCompletionById.get(block.id);
                const lessonOffset = learningBlocks.slice(0, blockIndex).reduce((sum, entry) => sum + entry.lessons.length, 0);
                return <div className="block-progress-group" key={block.id}>
                  <div className="block-progress-title"><div><span>{blockIndex + 1}</span><strong>{block.title}</strong></div><small>{blockResult ? `Итоговый тест пройден ${formatMoment(blockResult.completedAt)}` : "Итоговый тест не пройден"}</small></div>
                  <div className="lesson-table-head" aria-hidden="true"><span>№</span><span>Урок</span><span>Пройдено</span><span>Статус</span><span>Прогресс</span><span>Дата и время</span></div>
                  {block.lessons.map((lesson, lessonIndex) => {
                    const saved = lessonProgressById.get(lesson.id);
                    const percent = saved?.percent || 0;
                    return <div className="lesson-progress-line" key={lesson.id}><span>{lessonOffset + lessonIndex + 1}</span><div><strong>{lesson.title}</strong><small>{block.title}</small></div><i className="lesson-progress-track" role="progressbar" aria-label={`Пройдено ${percent}% урока ${lesson.title}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent}><span style={{ width: `${percent}%` }}/></i><em className={`progress-status ${percent === 100 ? "done" : percent > 0 ? "started" : "idle"}`}>{percent === 100 ? "Пройден" : percent > 0 ? "В процессе" : "Не начат"}</em><b>{percent}%</b><time>{saved ? formatMoment(saved.completedAt) : "—"}</time></div>;
                  })}
                </div>;
              })}
            </section>
          </div>
        </article>;
      })}{!loading && !users.length && <p className="empty">Зарегистрированных пользователей пока нет.</p>}</div>
    </section>
  </>;
}

function VideoCard({ onSubmitted }: { onSubmitted: (submittedAt: string) => void }) {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState("");
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState("");
  const [uploading, setUploading] = useState(false);

  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview); }, [preview]);

  const chooseVideo = (event: React.ChangeEvent<HTMLInputElement>) => {
    const selected = event.currentTarget.files?.[0];
    if (!selected) return;
    if (!selected.type.startsWith("video/")) { setError("Выберите видеофайл."); return; }
    if (selected.size > 100 * 1024 * 1024) { setError("Размер видео не должен превышать 100 МБ."); return; }
    if (preview) URL.revokeObjectURL(preview);
    const url = URL.createObjectURL(selected);
    const probe = document.createElement("video");
    probe.preload = "metadata";
    probe.onloadedmetadata = () => {
      const seconds = Math.round(probe.duration);
      if (seconds < 60 || seconds > 130) {
        setError("Запишите видео длительностью от 1 до 2 минут 10 секунд.");
        setFile(null);
        URL.revokeObjectURL(url);
      } else {
        setFile(selected);
        setPreview(url);
        setDuration(seconds);
        setError("");
      }
    };
    probe.onerror = () => { setError("Не удалось прочитать видео. Попробуйте другой файл."); URL.revokeObjectURL(url); };
    probe.src = url;
  };

  const submit = async () => {
    if (!file) return;
    setUploading(true);
    setError("");
    try {
      const form = new FormData();
      form.append("video", file);
      form.append("durationSeconds", String(duration));
      const response = await fetch("/api/video-card", { method: "POST", body: form });
      const data = await response.json() as { submittedAt?: string; error?: string };
      if (!response.ok || !data.submittedAt) throw new Error(data.error || "Не удалось отправить видеовизитку.");
      onSubmitted(data.submittedAt);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Не удалось отправить видеовизитку.");
    } finally {
      setUploading(false);
    }
  };

  return <>
    <section className="page-heading"><div><Badge tone="date">Финальный шаг</Badge><h1>Видеовизитка</h1><p>Запишите короткое видео на телефон и представьтесь будущей команде.</p></div><Badge tone="active">1–2 минуты</Badge></section>
    <section className="video-card-layout"><article className="card video-brief"><h2>О чём рассказать</h2><ol><li><span>1</span><div><strong>О себе</strong><p>Кто вы, в каком городе работаете и чем занимаетесь сейчас.</p></div></li><li><span>2</span><div><strong>Сильные стороны</strong><p>Какие качества помогают вам выстраивать доверие и доводить диалог до результата.</p></div></li><li><span>3</span><div><strong>Опыт</strong><p>Расскажите об опыте продаж, партнёрств или привлечения инвестиций.</p></div></li></ol><aside className="green-callout"><CheckCircle2 size={20}/><p>Говорите естественно. Нам важны ясность, мотивация и умение кратко представить свой опыт.</p></aside></article>
      <article className="card video-recorder"><div className="card-kicker"><span><Sparkles size={17}/> Запись с телефона</span><Badge tone="neutral">до 100 МБ</Badge></div>{preview ? <><video src={preview} controls playsInline/><div className="video-file-summary"><div><strong>{file?.name}</strong><small>{Math.floor(duration / 60)}:{String(duration % 60).padStart(2, "0")} · {(Number(file?.size || 0) / 1024 / 1024).toFixed(1)} МБ</small></div><label className="secondary-button">Перезаписать<input type="file" accept="video/*" capture="user" onChange={chooseVideo}/></label></div></> : <label className="camera-upload"><span><Sparkles size={28}/></span><strong>Записать видеовизитку</strong><p>На телефоне откроется камера. Держите устройство вертикально, выберите тихое и хорошо освещённое место.</p><em>Открыть камеру</em><input type="file" accept="video/*" capture="user" onChange={chooseVideo}/></label>}{error && <p className="video-error" role="alert">{error}</p>}<button className="primary-button video-submit" disabled={!file || uploading} onClick={submit}>{uploading ? "Загружаем видео…" : "Отправить видеовизитку"}<ArrowRight size={17}/></button></article>
    </section>
  </>;
}

